const safeHref = { fr:'/safe-certification-immobiliere/', en:'/en/safe-real-estate-certification/', es:'/es/certificacion-inmobiliaria-safe/', nl:'/nl/safe-vastgoedcertificering/' };
const articleRoot = { fr:'/articles/', en:'/en/articles/', es:'/es/articulos/', nl:'/nl/artikelen/' };
const dirByLocale = { fr:'src/content/articles', en:'src/content/articles/en', es:'src/content/articles/es', nl:'src/content/articles/nl' };
function words(s){return s.split(/\s+/).filter(Boolean).length;}
function mdTable(headers, rows){ return `| ${headers.join(' | ')} |\n|${headers.map(()=> '---').join('|')}|\n${rows.map(r=>`| ${r.join(' | ')} |`).join('\n')}`; }
function faq(items){ return `\n## FAQ\n\n${items.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('\n\n')}\n`; }
function img(key, alt, caption){ const im=imageMeta[key]; return `\n<figure>\n  <img src="${im.localPath}" alt="${alt}" width="1600" height="900" loading="lazy" />\n  <figcaption>${caption}</figcaption>\n</figure>\n`; }
function fm(data){ return `---\n${YAML.stringify(data).trim()}\n---\n\n`; }
function writeArticle(a){
  for (const l of ['fr','en','es','nl']) {
    const local=a.locales[l];
    const im=imageMeta[a.imageKey];
    const data={
      title: local.title,
      slug: local.slug,
      urlSlug: local.slug,
      locale: l,
      translationKey: a.key,
      metaTitle: local.metaTitle,
      metaDescription: local.metaDescription,
      category: a.category,
      tags: local.tags,
      date,
      updatedDate: date,
      readingTime: Math.max(6, Math.round(words(local.body)/220)),
      excerpt: local.excerpt,
      heroImage: im.localPath,
      imageAlt: local.imageAlt,
      articleType: 'Article',
      heroCaption: local.heroCaption,
      heroCredit: `${im.artist || im.credit} / ${im.license}`,
      heroSource: im.sourceUrl,
      heroLicense: im.licenseUrl || im.sourceUrl,
      heroWidth: 1600,
      heroHeight: 900,
      featured: !!a.featured,
      sources: local.sources,
      disclaimer: true,
    };
    const file=path.join(dirByLocale[l], `${local.slug}.md`);
    fs.mkdirSync(path.dirname(file),{recursive:true});
    fs.writeFileSync(file, fm(data)+local.body.trim()+`\n`);
    console.log(file, words(local.body));
  }
}
